def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    DIV_ZERO = "#DIV/0!"
    CYCLE = "#CYCLE!"
    function_names = {"SUM", "MIN", "MAX", "IF"}
    token_pattern = re.compile(
        r"[0-9]+|[A-Z]+[0-9]*|<=|>=|<>|[-+*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def parse_integer(text):
        text = text.strip()
        if len(text) <= 18:
            return int(text)

        # Chunk conversion also supports literals beyond Python's digit limit.
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]

        number = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            number = number * (10 ** len(chunk)) + int(chunk)
        return sign * number

    def parse(expression):
        operands = []
        operators = []
        parentheses = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append((op, left, right))

        for match in token_pattern.finditer(expression):
            token = match.group()

            if token[0].isdigit():
                operands.append(parse_integer(token))
                expect_operand = False

            elif token in function_names:
                operators.append(token)
                expect_operand = True

            elif token[0].isalpha():
                operands.append(("ref", token))
                expect_operand = False

            elif token == "(":
                function = (
                    operators[-1]
                    if operators and operators[-1] in function_names
                    else None
                )
                parentheses.append((len(operands), function))
                operators.append("(")
                expect_operand = True

            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                expect_operand = True

            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()

                start, function = parentheses.pop()
                if function is not None:
                    operators.pop()
                    arguments = tuple(operands[start:])
                    del operands[start:]
                    operands.append((function, arguments))
                expect_operand = False

            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and operators[-1] in precedence:
                    top = operators[-1]
                    if precedence[top] < precedence[op]:
                        break
                    if precedence[top] == precedence[op] and op == "neg":
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return operands[0]

    def argument_nodes(arguments):
        for node in arguments:
            if isinstance(node, tuple) and node[0] == ":":
                first, last = node[1][1], node[2][1]
                col_low, col_high = sorted((ord(first[0]), ord(last[0])))
                row_low, row_high = sorted((int(first[1:]), int(last[1:])))

                for row in range(row_low, row_high + 1):
                    for col in range(col_low, col_high + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield ("ref", name)
            else:
                yield node

    results = {}
    active = set()
    value = 0

    # Both parsing and evaluation use explicit stacks.
    for root in cells:
        if root in results:
            continue

        tasks = [("cell", root)]

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name in results:
                    value = results[name]
                elif name in active:
                    value = CYCLE
                elif name not in cells:
                    value = 0
                else:
                    content = cells[name]
                    if content.startswith("="):
                        active.add(name)
                        tasks.append(("save", name))
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        value = parse_integer(content)
                        results[name] = value

            elif action == "save":
                name = task[1]
                results[name] = value
                active.remove(name)

            elif action == "eval":
                node = task[1]
                if isinstance(node, int):
                    value = node
                    continue

                kind = node[0]
                if kind == "ref":
                    tasks.append(("cell", node[1]))
                elif kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))
                elif kind == "IF":
                    condition, then_branch, else_branch = node[1]
                    tasks.append(("choose", then_branch, else_branch))
                    tasks.append(("eval", condition))
                elif kind in {"SUM", "MIN", "MAX"}:
                    nodes = argument_nodes(node[1])
                    tasks.append(("aggregate_next", kind, nodes, None))
                else:
                    tasks.append(("left_done", kind, node[2]))
                    tasks.append(("eval", node[1]))

            elif action == "negate":
                if not isinstance(value, str):
                    value = -value

            elif action == "left_done":
                if not isinstance(value, str):
                    tasks.append(("binary", task[1], value))
                    tasks.append(("eval", task[2]))

            elif action == "binary":
                if isinstance(value, str):
                    continue

                op, left, right = task[1], task[2], value
                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = DIV_ZERO
                    else:
                        quotient = abs(left) // abs(right)
                        value = (
                            -quotient
                            if (left < 0) != (right < 0)
                            else quotient
                        )
                elif op == "=":
                    value = int(left == right)
                elif op == "<>":
                    value = int(left != right)
                elif op == "<":
                    value = int(left < right)
                elif op == "<=":
                    value = int(left <= right)
                elif op == ">":
                    value = int(left > right)
                elif op == ">=":
                    value = int(left >= right)

            elif action == "choose":
                if not isinstance(value, str):
                    branch = task[1] if value else task[2]
                    tasks.append(("eval", branch))

            elif action == "aggregate_next":
                function, nodes, accumulator = task[1:]
                node = next(nodes, None)
                if node is None:
                    value = 0 if accumulator is None else accumulator
                else:
                    tasks.append(
                        ("accumulate", function, nodes, accumulator)
                    )
                    tasks.append(("eval", node))

            elif action == "accumulate":
                if isinstance(value, str):
                    continue

                function, nodes, accumulator = task[1:]
                if accumulator is None:
                    accumulator = value
                elif function == "SUM":
                    accumulator += value
                elif function == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append(
                    ("aggregate_next", function, nodes, accumulator)
                )

    return {name: results[name] for name in cells}
